package com.spamemailnew.backend.controller; import com.spamemailnew.backend.model.*; import com.spamemailnew.backend.service.NaiveBayesClassifier; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api") @CrossOrigin(origins="*") public class PredictionController { private final NaiveBayesClassifier c; public PredictionController(NaiveBayesClassifier c){this.c=c;} @GetMapping("/health") public String health(){return "Spam Email Classifier API is running";} @PostMapping("/predict") public ResponseEntity<PredictionResponse> predict(@RequestBody PredictionRequest r){if(r==null||r.text()==null||r.text().isBlank())return ResponseEntity.badRequest().body(new PredictionResponse("UNKNOWN",0,0,"Please enter an email message."));var x=c.predict(r.text());return ResponseEntity.ok(new PredictionResponse(x.label(),x.spamProbability(),x.hamProbability(),x.label().equals("SPAM")?"This message looks suspicious.":"This message looks like a normal email."));}}